/*
 * A183171  Second of two trees generated by the Beatty sequence of sqrt(2).
 * https://oeis.org/A183171
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 23, u16 n <= 511, u32 n <= 8192, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A183171:  Second tree generated by the Beatty sequence of √2.
   a(1) = 2, a(2) = 6.  The sequence is produced by a breadth‑first
   traversal of a binary tree whose root is 6.  For a node x the
   children are
          L = ⌊x·√2⌋
          U = ⌊x·(√2+2)⌋ = L + 2·x
   All nodes are visited once, in the order they are discovered; the
   sequence is the list of those node values.  The implementation
   below stores the terms in a dynamically resizing cache and
   expands the tree as needed, so that a(n) can be obtained in O(n)
   time in any order of calls. */

#include <stdlib.h>
#include <stdint.h>
#include <string.h>

/* ------------------------------------------------------------ */
/* Integer square root of a 128‑bit unsigned integer, used for
   floor(√(2·x²)) and for all other square‑root computations. */
static inline unsigned __int128 isqrt128(unsigned __int128 v)
{
    unsigned __int128 low = 0;
    const unsigned bits = sizeof(unsigned __int128) * 8;
    unsigned __int128 high = ((unsigned __int128)1) << ((bits + 1) >> 1);
    while (low < high) {
        unsigned __int128 mid = (low + high + 1) >> 1;
        if (mid * mid <= v)
            low = mid;
        else
            high = mid - 1;
    }
    return low;
}

/* ------------------------------------------------------------ */
/* Cache of already computed sequence terms.  The cache is
   resized in powers of two to keep append operations O(1). */
static seq_t *seq_cache = NULL;  /* seq_t array of computed terms */
static idx_t  seq_len  = 0;      /* current number of stored terms */
static size_t seq_cap  = 0;      /* allocated capacity */

/* Queue of node values that still need to be expanded.
   The queue is a circular buffer with dynamic growth. */
static idx_t *queue = NULL;
static size_t q_head = 0;   /* index of next element to pop   */
static size_t q_tail = 0;   /* index of next free slot        */
static size_t q_cap  = 0;   /* allocated capacity             */

/* ------------------------------------------------------------ */
/* Ensure the cache can hold at least `need` more elements. */
static void cache_ensure(idx_t need)
{
    if (seq_len + need <= seq_cap)
        return;
    size_t new_cap = seq_cap ? seq_cap << 1 : 64;
    while (new_cap < seq_len + need)
        new_cap <<= 1;
    seq_t *new_mem = (seq_t*)malloc(new_cap * sizeof(seq_t));
    if (!new_mem) exit(1);          /* OOM – acceptable in this context */
    if (seq_cache) {
        memcpy(new_mem, seq_cache, seq_len * sizeof(seq_t));
        free(seq_cache);
    }
    seq_cache = new_mem;
    seq_cap   = new_cap;
}

/* ------------------------------------------------------------ */
/* Ensure the queue has space; if the tail has wrapped, shift
   contents to the front. */
static void queue_ensure(void)
{
    if (q_head == q_tail)          /* empty queue */
        return;
    if (q_tail < q_cap)            /* space at end */
        return;
    size_t active = q_tail - q_head;
    size_t new_cap = q_cap ? q_cap << 1 : 64;
    while (new_cap < active)
        new_cap <<= 1;
    idx_t *new_mem = (idx_t*)malloc(new_cap * sizeof(idx_t));
    if (!new_mem) exit(1);
    memcpy(new_mem, queue + q_head, active * sizeof(idx_t));
    free(queue);
    queue = new_mem;
    q_cap = new_cap;
    q_tail = active;
    q_head = 0;
}

/* Enqueue a new value onto the queue. */
static void enqueue(idx_t val)
{
    queue_ensure();
    queue[q_tail++] = val;
}

/* ------------------------------------------------------------ */
/* Helper: compute L = floor(x·√2) as floor(√(2·x²)). */
static inline seq_t floor_L(idx_t x)
{
    unsigned __int128 twoxsq = (unsigned __int128)2 * x * x;
    unsigned __int128 root   = isqrt128(twoxsq);
    return (seq_t)root;
}

/* ------------------------------------------------------------ */
/* Main function to compute a(n). */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                    /* undefined but safe */

    /* One‑time initialisation of cache and queue. */
    if (seq_len == 0) {
        cache_ensure(2);
        seq_cache[0] = (seq_t)2;             /* a(1) */
        seq_cache[1] = (seq_t)6;             /* a(2) */
        seq_len = 2;

        q_cap = 64;
        queue = (idx_t*)malloc(q_cap * sizeof(idx_t));
        q_head = q_tail = 0;
        enqueue((idx_t)6);                   /* start with the root node 6 */
    }

    /* Generate new terms until we have at least n. */
    while (seq_len < n) {
        if (q_head >= q_tail)                /* queue empty – should not happen */
            break;
        idx_t x = queue[q_head++];
        seq_t L = floor_L(x);
        seq_t U = L + (seq_t)((unsigned __int128)x * 2);

        cache_ensure(2);
        seq_cache[seq_len++] = L;
        seq_cache[seq_len++] = U;

        enqueue((idx_t)L);
        enqueue((idx_t)U);
    }

    return seq_cache[n - 1];
}
